mapper.select:
SELECT src.tenant_id, src.project_id, COALESCE(p.name, src.project_id) AS name, COALESCE(p.status, 'ACTIVE') AS status, MIN(src.created_at) AS created_at FROM ( SELECT tenant_id, project_id, created_at FROM api_keys WHERE tenant_id IS NOT NULL AND project_id IS NOT NULL UNION ALL SELECT tenant_id, project_id, created_at FROM rag_documents UNION ALL SELECT tenant_id, project_id, created_at FROM projects ) src LEFT JOIN projects p ON p.tenant_id = src.tenant_id AND p.project_id = src.project_id
src.tenant_id = #{tenantId,jdbcType=VARCHAR}
AND COALESCE(p.status, 'ACTIVE') = #{status,jdbcType=VARCHAR}
GROUP BY src.tenant_id, src.project_id, p.name, p.status ORDER BY src.tenant_id ASC, src.project_id ASC LIMIT #{limit,jdbcType=INTEGER} OFFSET #{offset,jdbcType=INTEGER}
